INSERT IGNORE INTO medallas (codigo, nombre, descripcion, icono, categoria, condicion, meta, idioma_id, nivel, color, orden) SELECT CONCAT('a2_', LOWER(i.codigo)), CONCAT('A2 de ', CASE i.codigo WHEN 'EN' THEN 'inglés' WHEN 'ES' THEN 'español' ELSE 'LSC' END), CONCAT('Terminaste el nivel A2 de ', CASE i.codigo WHEN 'EN' THEN 'inglés' WHEN 'ES' THEN 'español' ELSE 'Lengua de Señas Colombiana' END), CASE i.codigo WHEN 'LSC' THEN 'fa-hands' ELSE 'fa-flag-checkered' END, 'ruta', 'ruta_nivel', 1, i.id, 'A2', 'morado', CASE i.codigo WHEN 'EN' THEN 113 WHEN 'ES' THEN 114 ELSE 115 END FROM idiomas i WHERE i.codigo IN ('EN', 'ES', 'LSC');
